define("openproject.config", {
  prefix: "openproject.config.",
  keys: [
    "delete.description.first",
    "delete.deleted",
    "delete.defaultConnection.replaced",
    "delete.errorOccurred",
    "defaultConnection.refreshFailed",
    "fillInAllFields",
    "invalidConnectionName",
    "save",
    "save.saved",
    "save.errorOccurred",
    "updateConnection",
    "createConnection",
  ],
});

require(["jquery", "xwiki-l10n!openproject.config"], function ($, l10n) {
  // The OAuth application (client id and secret) is only needed when the users can connect their OpenProject account.
  function getAccessMode() {
    return $("input[name='access-mode']:checked").val() || "USER_ACCOUNTS";
  }

  function updateOAuthApplicationFields() {
    $(".oauth-application-field").prop("hidden", getAccessMode() == "PUBLIC_DATA");
  }

  function setAccessMode(accessMode) {
    const radio = $("input[name='access-mode']").filter(function () {
      return this.value == accessMode;
    });
    (radio.length ? radio : $("input[name='access-mode'][value='USER_ACCOUNTS']")).prop("checked", true);
    updateOAuthApplicationFields();
  }

  // The default connection is chosen in another section of the administration, below the connections.
  function getDefaultConnectionSelect() {
    return $("select[name$='_defaultConnection']");
  }

  // The saved default connection, which may differ from the one currently selected.
  function getSavedDefaultConnection() {
    return getDefaultConnectionSelect().find("option").filter(function () {
      return this.defaultSelected;
    }).val() || "";
  }

  // Saving, renaming or deleting a connection can change the connections that can be chosen as the default one, and
  // the default connection itself (e.g. the first connection becomes the default one when a second one is added).
  async function refreshDefaultConnectionSelect() {
    const select = getDefaultConnectionSelect();
    if (!select.length) {
      return;
    }
    select.attr("data-refreshing", "true");
    try {
      const page = $("<div>").append($.parseHTML(await $.get(window.location.href)));
      const freshSelect = page.find("select[name$='_defaultConnection']");
      if (freshSelect.length) {
        select.html(freshSelect.html()).val(freshSelect.val());
      }
    } catch (e) {
      // Saving the current choice could revert a change of the default connection made when saving the connection.
      // The notification message is HTML.
      new XWiki.widgets.Notification(l10n.get("defaultConnection.refreshFailed").escapeHTML(), "error");
    } finally {
      select.removeAttr("data-refreshing");
    }
  }

  $(document).ready(function () {
    $(document).on("change", "input[name='access-mode']", updateOAuthApplicationFields);
    // Keep the saved default connection up to date once the administration form is saved. The event is fired by
    // Prototype.
    document.observe("xwiki:document:saved", refreshDefaultConnectionSelect);

    $(document).on("click", ".edit-button", function () {
      $("#handleConnectionModal").modal("show");
      $("#handleConnectionModal-label").text(l10n.get("updateConnection"));
      // Read the attributes as strings, without any type conversion.
      const connectionName = $(this).attr("data-connection-name");
      const serverURL = $(this).attr("data-server-url");
      const clientId = $(this).attr("data-client-id");
      const documentReference = $(this).attr("data-edit-document-reference");
      // Remember the current name, which is kept even if it isn't valid anymore (see the save below).
      $("#connection-name").val(connectionName).data("currentName", connectionName);
      $("#server-url").val(serverURL.replace(/\\\//g, "/"));
      $("#client-id").val(clientId);
      // The current client secret is not sent to the browser: leaving the field empty keeps it.
      $("#client-secret").val("");
      $("#client-secret-keep-hint").prop("hidden", false);
      setAccessMode($(this).attr("data-access-mode"));
      $("#document-reference").val(documentReference);
      $("#connection-action").val("edit");
    });

    $("#create-connection-button").on("click", function () {
      $("#handleConnectionModal").modal("show");
      $("#handleConnectionModal-label").text(l10n.get("createConnection"));
      $("#connection-name").val("").removeData("currentName");
      $("#server-url").val("");
      $("#client-id").val("");
      $("#client-secret").val("");
      $("#client-secret-keep-hint").prop("hidden", true);
      setAccessMode("USER_ACCOUNTS");

      const connectionsSpace = XWiki.Model.resolve(
        "OpenProject.Code.OpenProjectConfigurations",
        XWiki.EntityType.SPACE,
        XWiki.currentDocument.getDocumentReference()
      );

      const configurationName = "Connection" + (crypto && crypto.randomUUID ?
        crypto.randomUUID() : Date.now());
      const connectionRef = XWiki.Model.resolve(
        configurationName,
        XWiki.EntityType.DOCUMENT,
        connectionsSpace
      );

      $("#document-reference").val(connectionRef);
      $("#connection-action").val("create");
    });

    $(document).on("click", ".delete-button", function () {
      $("#deleteConnectionModal").modal("show");
      const connectionName = $(this).attr("data-connection-name");
      const deleteDocumentReference = $(this).attr("data-delete-document-reference");
      $("#delete-connection-document-reference").val(deleteDocumentReference);
      $("#delete-connection-name").val(connectionName);
      $("#delete-connection-confirmation-message").text(
        `${l10n.get("delete.description.first", connectionName)}?`
      );
      // The macros that don't specify a connection use the default connection, i.e. the only connection or the saved
      // default one. Once it's deleted, they stop working when several connections remain, without a default one,
      // and use the remaining connection when a single one remains. No macro works once the last one is deleted.
      const connections = getDefaultConnectionSelect().find("option[value!='']").map(function () {
        return this.value;
      }).get();
      const remainingConnections = connections.filter(name => name !== connectionName);
      const isDefault = connections.length === 1 || getSavedDefaultConnection() === connectionName;
      $("#delete-connection-last-warning").prop("hidden", remainingConnections.length > 0);
      $("#delete-connection-default-warning").prop("hidden", !isDefault || remainingConnections.length < 2);
      $("#delete-connection-replaced-warning").prop("hidden", !isDefault || remainingConnections.length !== 1)
        .text(remainingConnections.length === 1
          ? l10n.get("delete.defaultConnection.replaced", remainingConnections[0]) : "");
    });

    $("#delete-connection-form").on("submit", async function (e) {
      e.preventDefault();
      const csrfToken = $("#delete-connection-form-token").val();
      const connectionName = $("#delete-connection-name").val();
      const documentReference = $(
        "#delete-connection-document-reference"
      ).val();
      const documentRestUrl = new XWiki.Document(
        XWiki.Model.resolve(documentReference, XWiki.EntityType.DOCUMENT)
      ).getRestURL();
      try {
        await $.ajax({
          method: "DELETE",
          headers: {
            "XWiki-Form-Token": csrfToken,
          },
          url: documentRestUrl,
        });

        $("#openproject_connections").data("liveData").updateEntries();
        refreshDefaultConnectionSelect();
        $("#deleteConnectionModal").modal("hide");

        // The notification message is HTML.
        new XWiki.widgets.Notification(
          l10n.get("delete.deleted", connectionName).escapeHTML(),
          "done"
        );
      } catch (e) {
        new XWiki.widgets.Notification(
          l10n.get("delete.errorOccurred"),
          "error"
        );
      }
    });

    $("#handle-connection-form").on("submit", async function (e) {
      e.preventDefault();
      const csrfToken = $("#create-connection-form-token").val();
      const connectionName = $("#connection-name").val().trim();
      const serverURL = $("#server-url").val().trim();
      const clientId = $("#client-id").val().trim();
      const clientSecret = $("#client-secret").val().trim();
      const accessMode = getAccessMode();
      const userAccounts = accessMode != "PUBLIC_DATA";
      const documentReference = $("#document-reference").val();
      const connectionAction = $("#connection-action").val();

      if (!connectionName || !serverURL
          || (userAccounts && (!clientId || (!clientSecret && connectionAction == "create")))) {
        return new XWiki.widgets.Notification(
          l10n.get("fillInAllFields"),
          "error"
        );
      }

      // The connection name is part of the REST URLs, where the servlet containers reject the encoded slashes and
      // percent signs, and where the dot segments are removed. The name of an existing connection is accepted as long
      // as it isn't changed, since renaming the connection would break the macros using it.
      const currentName = connectionAction == "edit" ? $("#connection-name").data("currentName") : undefined;
      if (connectionName !== currentName
          && (/[\/\\%]/.test(connectionName) || /^\.+$/.test(connectionName))) {
        return new XWiki.widgets.Notification(l10n.get("invalidConnectionName").escapeHTML(), "error");
      }

      const connectionRef = XWiki.Model.resolve(
        documentReference,
        XWiki.EntityType.DOCUMENT
      );
      const url = new XWiki.Document(connectionRef).getRestURL(
        "openproject/configurations"
      );

      try {
        await $.ajax({
          method: connectionAction == "create" ? "POST" : "PUT",
          contentType: "application/json",
          url: url,
          headers: {
            "XWiki-Form-Token": csrfToken,
          },
          data: JSON.stringify({
            connectionName: connectionName,
            serverURL: serverURL,
            clientId: clientId,
            clientSecret: clientSecret,
            accessMode: accessMode,
          }),
        });

        $("#openproject_connections").data("liveData").updateEntries();
        refreshDefaultConnectionSelect();
        $("#handleConnectionModal").modal("hide");

        // The notification message is HTML.
        new XWiki.widgets.Notification(
          l10n.get("save.saved", connectionName).escapeHTML(),
          "done"
        );
      } catch (e) {
        new XWiki.widgets.Notification(
          (e.responseText ?? l10n.get("save.errorOccurred", connectionName)).escapeHTML(),
          "error"
        );
      }
    });
  });
});
